const $ = (id) => document.getElementById(id);
const zone = $('dropZone'); const input = $('fileInput'); const state = $('uploadState');
const result = $('result'); const canvas = $('map'); const ctx = canvas.getContext('2d');
let motion = null; let viewMode = 'full';
function choose(){ input.click(); }
function setState(text, error=false){ state.textContent=text; state.style.color=error?'#ed6a54':'#159b8b'; }
function yawLabel(rad){ let deg=rad*180/Math.PI; if(deg>180)deg-=360;if(deg<=-180)deg+=360; return `${deg.toFixed(1)}°`; }
function arrow(x,y,yaw,color,size=18){ ctx.save();ctx.translate(x,y);ctx.rotate(-yaw);ctx.fillStyle=color;ctx.beginPath();ctx.moveTo(size,0);ctx.lineTo(-size*.7,-size*.55);ctx.lineTo(-size*.35,0);ctx.lineTo(-size*.7,size*.55);ctx.closePath();ctx.fill();ctx.restore(); }
function draw(){
  if(!motion)return;
  const frames=motion.frames, points=viewMode==='full'?frames.flatMap(f=>[f.position,f.leftFoot,f.rightFoot]):[motion.start.position,motion.end.position];
  const xs=points.map(p=>p[0]),ys=points.map(p=>p[1]); let minX=Math.min(...xs),maxX=Math.max(...xs),minY=Math.min(...ys),maxY=Math.max(...ys),pad=Math.max(.5,Math.max(maxX-minX,maxY-minY)*.18);minX-=pad;maxX+=pad;minY-=pad;maxY+=pad;
  const w=canvas.width,h=canvas.height,scale=Math.min((w-90)/(maxX-minX),(h-70)/(maxY-minY)),ox=45-minX*scale,oy=25+maxY*scale,point=p=>[ox+p[0]*scale,oy-p[1]*scale];
  ctx.clearRect(0,0,w,h);ctx.strokeStyle='#d2d7c9';ctx.lineWidth=1;for(let i=Math.ceil(minX*10);i<=Math.floor(maxX*10);i++){const x=ox+i/10*scale;ctx.beginPath();ctx.moveTo(x,20);ctx.lineTo(x,h-35);ctx.stroke()}for(let i=Math.ceil(minY*10);i<=Math.floor(maxY*10);i++){const y=oy-i/10*scale;ctx.beginPath();ctx.moveTo(35,y);ctx.lineTo(w-25,y);ctx.stroke()}
  const path=(key,color,dash=[])=>{ctx.beginPath();ctx.setLineDash(dash);frames.forEach((f,i)=>{const q=point(f[key]);i?ctx.lineTo(...q):ctx.moveTo(...q)});ctx.strokeStyle=color;ctx.lineWidth=key==='position'?4:2;ctx.stroke();ctx.setLineDash([])};
  if(viewMode==='full'){path('leftFoot','#9ca9a1',[7,6]);path('rightFoot','#9ca9a1',[7,6]);path('position','#18201f');}else{const start=point(motion.start.position),end=point(motion.end.position);ctx.strokeStyle='#18201f';ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(...start);ctx.lineTo(...end);ctx.stroke();}
  const first=point(motion.start.position),last=point(motion.end.position);ctx.fillStyle='#159b8b';ctx.beginPath();ctx.arc(...first,7,0,Math.PI*2);ctx.fill();arrow(...first,motion.start.yaw,'#159b8b');ctx.fillStyle='#ed6a54';ctx.beginPath();ctx.arc(...last,7,0,Math.PI*2);ctx.fill();arrow(...last,motion.end.yaw,'#ed6a54');
}
function setView(mode){viewMode=mode;$('fullViewButton').classList.toggle('selected',mode==='full');$('lineViewButton').classList.toggle('selected',mode==='line');draw();}
function render(data){ motion=data; result.classList.remove('hidden');$('filename').textContent=data.filename;$('duration').textContent=`${((data.frameCount-1)/data.fps).toFixed(2)} s`;$('displacement').textContent=`${data.displacement.distance.toFixed(3)} m`;$('headingChange').textContent=yawLabel(data.headingChange);$('finalHeading').textContent=yawLabel(data.end.yaw);$('frameSummary').textContent=`起点 ${yawLabel(data.start.yaw)} · 终点 ${yawLabel(data.end.yaw)} · 选择显示方式`;setView('full');result.scrollIntoView({behavior:'smooth',block:'start'});}
async function load(file){if(!file)return;if(!file.name.toLowerCase().endsWith('.onnx')){setState('请选择 .onnx 文件。',true);return}setState('正在读取 ONNX 起终点和轨迹…');try{const response=await fetch('/api/trajectory',{method:'POST',headers:{'Content-Type':'application/octet-stream','X-Filename':file.name},body:file});const data=await response.json();if(!response.ok)throw new Error(data.error||'解析失败');render(data);setState('解析完成。');}catch(error){setState(error.message,true)}}
zone.addEventListener('click',choose);$('chooseButton').addEventListener('click',e=>{e.stopPropagation();choose()});zone.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();choose()}});input.addEventListener('change',e=>load(e.target.files[0]));['dragenter','dragover'].forEach(type=>zone.addEventListener(type,e=>{e.preventDefault();zone.classList.add('active')}));['dragleave','drop'].forEach(type=>zone.addEventListener(type,e=>{e.preventDefault();zone.classList.remove('active')}));zone.addEventListener('drop',e=>load(e.dataTransfer.files[0]));$('fullViewButton').addEventListener('click',()=>motion&&setView('full'));$('lineViewButton').addEventListener('click',()=>motion&&setView('line'));
